select * from airbnb.customer_dim;


DBCC FREEPROCCACHE;


TRUNCATE TABLE airbnb.customer_dim;


TRUNCATE TABLE airbnb.bookings_dim;


RENAME OBJECT airbnb.bookings_fact TO bookings_dim;


SELECT 
    name AS procedure_name
FROM 
    sys.procedures
WHERE 
    type = 'P'
ORDER BY 
    procedure_name;


DROP PROCEDURE airbnb.BookingAggregation;


CREATE USER [project-data-factory-instance] FROM EXTERNAL PROVIDER;
EXEC sp_addrolemember 'db_datareader', 'project-data-factory-instance';
EXEC sp_addrolemember 'db_datawriter', 'project-data-factory-instance';
EXEC sp_addrolemember 'db_owner', 'project-data-factory-instance';


GRANT SELECT, INSERT, UPDATE, DELETE, CONTROL ON SCHEMA::airbnb TO [project-data-factory-instance];


SELECT 
    dp.name AS PrincipalName,
    dp.type_desc AS PrincipalType,
    p.permission_name AS PermissionName,
    p.state_desc AS PermissionState
FROM 
    sys.database_permissions p
JOIN 
    sys.database_principals dp ON p.grantee_principal_id = dp.principal_id
WHERE dp.name = 'project-data-factory-instance';


SELECT 
    name AS SchemaName,
    schema_id AS SchemaID,
    principal_id AS OwnerPrincipalID
FROM 
    sys.schemas
ORDER BY 
    name;


SELECT 
    name AS ObjectName,
    type_desc AS ObjectType
FROM 
    sys.objects
WHERE 
    schema_id = SCHEMA_ID('db_accessadmin');

DROP SCHEMA airbnb;
